#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Bootstraps one copy of iac-aws, from a brand-new AWS account to CI deploying the org.
# Run from the repo root: bash scripts/bootstrap.sh
#
# The temporary root access key lives only in this process's environment. It is never
# written to disk, and the last stage has you delete it.
#
# Keep STATE_KEY_ALIAS and the bucket name in sync with src/state.ts.

TOTAL_STAGES=8

STACK="main"
STATE_KEY_ALIAS="alias/iac-aws-state"

# AWS CLI on Windows prints CRLF; strip it so captured values compare cleanly.
awsq() { aws "$@" | tr -d '\r'; }
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

[[ -f Pulumi.yaml && -d policies/scp ]] || { printf 'Run this from the iac-aws repo root.\n' >&2; exit 1; }
[[ -f org.yaml ]] || { printf 'No org.yaml. Copy org.example.yaml to org.yaml, fill it in, then re-run.\n' >&2; exit 1; }

REGION=$(sed -n 's/^region:[[:space:]]*\([a-z0-9-]*\).*/\1/p' org.yaml)
SELF_REPO=$(sed -n 's/^selfRepo:[[:space:]]*\([^[:space:]#]*\).*/\1/p' org.yaml)

banner "iac-aws bootstrap"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check tools and org.yaml"
missing=()
for tool in node npm pulumi aws gh git; do command -v "$tool" >/dev/null 2>&1 || missing+=("$tool"); done
if (( ${#missing[@]} )); then
  warn "missing: ${missing[*]}. Install them and re-run."
  exit 1
fi
say "Installing dependencies and validating org.yaml…"
npm ci --silent --no-audit --no-fund
if ! npm test --silent >/dev/null 2>&1; then
  warn "Tests failed. Run 'npm test' to see what is wrong with org.yaml."
  exit 1
fi
ok "org.yaml is valid · region $REGION · repo $SELF_REPO"
current_repo=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || true)
if [[ "$current_repo" != "$SELF_REPO" ]]; then
  warn "selfRepo in org.yaml is '$SELF_REPO' but this checkout is '${current_repo:-unknown}'."
  warn "GitHub will only trust '$SELF_REPO', and the variables will be set on '${current_repo:-unknown}'."
  confirm "Continue anyway?" || exit 1
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the management account"
say "Each organization needs its own, brand-new AWS account to be its management account."
note "Use a fresh plus-address, e.g. you+org-<name>@gmail.com. Member accounts use the"
note "accountEmail pattern from org.yaml."
open_url "https://portal.aws.amazon.com/billing/signup"
step "Sign up with that email. The Basic (free) support plan is enough."
step "Once the account is active, sign in as the root user."
pause "Press Enter once you're signed in as root."
open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
step "Under 'Multi-factor authentication (MFA)', click 'Assign MFA device' and finish the setup."
pause "Press Enter once MFA is on."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Temporary root access key"
say "Pulumi needs credentials for the very first deploy. After that, CI uses OIDC and this key is deleted."
open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
step "Under 'Access keys', click 'Create access key', tick the acknowledgement, then 'Create access key'."
step "Copy the Access key ID and the Secret access key. Keep the page open until both are pasted."
ask AWS_ACCESS_KEY_ID "Access key ID:"
ask_secret AWS_SECRET_ACCESS_KEY "Secret access key:"
export AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY
export AWS_REGION="$REGION" AWS_DEFAULT_REGION="$REGION"
unset AWS_PROFILE AWS_SESSION_TOKEN
if ! identity=$(awsq sts get-caller-identity --query '[Account,Arn]' --output text 2>/dev/null); then
  warn "AWS rejected that key. Re-run and paste it again."
  exit 1
fi
ACCOUNT_ID=$(cut -f1 <<<"$identity")
ok "signed in to account $ACCOUNT_ID as $(cut -f2 <<<"$identity")"
if awsq organizations describe-organization >/dev/null 2>&1; then
  warn "This account already belongs to an organization. iac-aws expects a brand-new account,"
  warn "unless you are re-running this wizard after the first deploy."
  confirm "Continue?" || exit 1
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
STATE_BUCKET="iac-aws-state-${ACCOUNT_ID}"
stage "State backend"
say "Pulumi keeps its state in S3 and encrypts secrets with KMS, both in this account:"
note "  bucket   s3://${STATE_BUCKET}  (versioned, private, TLS only)"
note "  KMS key  ${STATE_KEY_ALIAS}  (automatic rotation)"
note "The stack never manages these itself, so it can never delete its own state."
if awsq kms describe-key --key-id "$STATE_KEY_ALIAS" >/dev/null 2>&1; then
  ok "KMS key $STATE_KEY_ALIAS already exists"
elif confirm "Create the KMS key?"; then
  key_id=$(awsq kms create-key --description "iac-aws Pulumi secrets" --query KeyMetadata.KeyId --output text)
  awsq kms create-alias --alias-name "$STATE_KEY_ALIAS" --target-key-id "$key_id"
  awsq kms enable-key-rotation --key-id "$key_id"
  ok "created KMS key $STATE_KEY_ALIAS"
else
  exit 1
fi
if awsq s3api head-bucket --bucket "$STATE_BUCKET" >/dev/null 2>&1; then
  ok "bucket $STATE_BUCKET already exists"
elif confirm "Create the state bucket?"; then
  if [[ "$REGION" == "us-east-1" ]]; then
    awsq s3api create-bucket --bucket "$STATE_BUCKET" >/dev/null
  else
    awsq s3api create-bucket --bucket "$STATE_BUCKET" \
      --create-bucket-configuration "LocationConstraint=$REGION" >/dev/null
  fi
  ok "created bucket $STATE_BUCKET"
else
  exit 1
fi
# Re-applied on every run so a half-finished earlier run converges.
tls_only_policy=$(printf '{"Version":"2012-10-17","Statement":[{"Sid":"TlsOnly","Effect":"Deny","Principal":"*","Action":"s3:*","Resource":["arn:aws:s3:::%s","arn:aws:s3:::%s/*"],"Condition":{"Bool":{"aws:SecureTransport":"false"}}}]}' "$STATE_BUCKET" "$STATE_BUCKET")
awsq s3api put-bucket-versioning --bucket "$STATE_BUCKET" --versioning-configuration Status=Enabled
awsq s3api put-public-access-block --bucket "$STATE_BUCKET" --public-access-block-configuration \
  BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true
awsq s3api put-bucket-policy --bucket "$STATE_BUCKET" --policy "$tls_only_policy"
ok "versioning, public access block and TLS-only policy in place"
PULUMI_BACKEND_URL="s3://${STATE_BUCKET}?region=${REGION}&awssdk=v2"
export PULUMI_BACKEND_URL
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Pulumi stack"
say "Creating stack '$STACK' in the S3 backend, with secrets encrypted by $STATE_KEY_ALIAS."
note "This shell uses PULUMI_BACKEND_URL; your global 'pulumi login' is left alone."
if pulumi stack select "$STACK" --non-interactive >/dev/null 2>&1; then
  ok "stack $STACK already exists"
else
  pulumi stack init "$STACK" --non-interactive \
    --secrets-provider "awskms://${STATE_KEY_ALIAS}?region=${REGION}"
  ok "created stack $STACK (Pulumi.$STACK.yaml holds its encrypted data key; it gets committed)"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "First deploy"
say "Pulumi shows what it is about to create and asks you to confirm."
note "Each new account takes a few minutes. If one isn't ready in time, re-run this wizard;"
note "every stage skips what is already done."
IAC_AWS_MODE=deploy pulumi up --stack "$STACK"
PLAN_ROLE_ARN=$(pulumi stack output planRoleArn --stack "$STACK" | tr -d '\r')
DEPLOY_ROLE_ARN=$(pulumi stack output deployRoleArn --stack "$STACK" | tr -d '\r')
ok "deployed · plan role $PLAN_ROLE_ARN"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Hand over to CI"
say "Setting the repo variables the preview and up workflows read."
set_var IAC_AWS_PLAN_ROLE_ARN "$PLAN_ROLE_ARN"
set_var IAC_AWS_DEPLOY_ROLE_ARN "$DEPLOY_ROLE_ARN"
set_var AWS_REGION "$REGION"
set_var PULUMI_BACKEND_URL "$PULUMI_BACKEND_URL"
[[ "$STACK" == "main" ]] || set_var PULUMI_STACK "$STACK"
say ""
say "org.yaml and Pulumi.$STACK.yaml need to be on main for CI to deploy."
if [[ -n "$(git status --porcelain -- org.yaml "Pulumi.$STACK.yaml")" ]]; then
  if confirm "Commit them and push to $(git rev-parse --abbrev-ref HEAD)?"; then
    git add org.yaml "Pulumi.$STACK.yaml"
    git commit -q -m "Bootstrap organization"
    git push -q
    ok "pushed"
    say "Waiting for the 'up' workflow, to prove CI can deploy without the root key…"
    run_id=""
    for _ in $(seq 1 12); do
      sleep 5
      run_id=$(gh run list --workflow up.yml --limit 1 --json databaseId --jq '.[0].databaseId' 2>/dev/null || true)
      [[ -n "$run_id" ]] && break
    done
    if [[ -n "$run_id" ]] && gh run watch "$run_id" --exit-status >/dev/null 2>&1; then
      ok "CI deployed successfully"
    else
      warn "The up workflow did not succeed, or could not be found. Check the Actions tab"
      warn "before deleting the key; problems are easier to fix with the key still in place."
    fi
  else
    SKIPPED+=("commit and push org.yaml and Pulumi.$STACK.yaml")
  fi
else
  ok "already committed"
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Delete the temporary key"
say "CI deploys through OIDC now. The root access key must go."
open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
step "Under 'Access keys', find $AWS_ACCESS_KEY_ID: Actions → Deactivate, then Actions → Delete."
pause "Press Enter once it's deleted."
if awsq sts get-caller-identity >/dev/null 2>&1; then
  warn "That key still works. Delete it before you walk away."
  SKIPPED+=("delete root access key $AWS_ACCESS_KEY_ID")
else
  ok "key $AWS_ACCESS_KEY_ID no longer works"
fi
unset AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY
note "From here on, Pulumi runs only in CI: edit org.yaml in a PR, read the preview, merge to apply."

finish
